            // Heavily penalize opening a new bin if we have fitting options.
            score += 150.0 * (1.0 - progress);
            // If we are near the end of the stream, be more aggressive with new bins.
            score -= 40.0 * progress;
        }
    } else {
        // If this is the last fitting bin, reward using it to avoid opening a new one later.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Balance: Avoid bins that deviate significantly from the mean residual.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.5 * deviation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

