    // Penalize empty bins exponentially as the stream progresses to discourage opening new bins late.
    let mut score = post_res;

    // Penalty for creating a bin that is too empty early on (fragmentation)
    // or too tight late in the game (risk of stranding).
    if bin_residual == bin_capacity {
        // High cost to open a new bin, weighted by current stream progress
        score += (bin_capacity as f64) * (1.0 + 2.0 * (1.0 - progress));
    } else {
        // Non-linear coupling: penalize bins that deviate significantly from the mean_residual
        // to encourage uniformity in bin usage.
        let residual_variance = (post_res - mean_residual).abs();
        score += residual_variance * 0.5;

        // Lookahead heuristic: if next_item_size is large, avoid leaving a residual
