    // 4. Fitting Pressure: If this is the only bin that can fit the current item, 
    // it is highly prioritized to keep the bin count low.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 5. Harmonic Modulo Bias: Favor residuals that align with common item size multiples (e.g., 20, 25, 33).
    // This helps maintain "packability" for subsequent items.
    let remainder_mod = post_residual % 20;
    if remainder_mod == 0 {
        score -= 5.0;
    }

    // 6. Progress Scaling: As the stream nears the end, prioritize closing bins (lower residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
