        // it's often worse than a slightly larger residual.
        if post_residual < 10 {
            score += 15.0 * (1.0 - progress);
        }
    } else {
        // Opening a new bin is expensive. We only do it if the existing options
        // are poor (high post_residual) or if we are forced to.
        score += 25.0 + (mean_residual * 0.3);
    }

    // 4. Scarcity Logic: If this is the only bin that can fit the item, 
