    } else {
        // Reward bins that keep the mean_residual high (balanced distribution).
        // Penalize bins that deviate too far from the mean.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.5;
    }

    // If this is the last chance for the current item (fitting_bins_count == 1),
    // reduce the penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
