    let mut score = post_residual as f64;

    // 1. Adaptive New Bin Penalty: Stricter enforcement early, relaxed late
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let base_penalty = 820.0; 
        score += base_penalty * (4.5 - progress.powf(0.06));
    }

    // 2. Predictive Lookahead Optimization: Prioritize exact matches and spatial headroom
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1850.0; 
        } else if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 280.0; 
        } else {
            score -= (next_item_size as f64 * 6.2) * (1.2 - progress.powf(0.4));
        }
    }

    // 3. Dynamic Consolidation: Density factor balancing current filling vs total open bins
    if open_bins_count > 0 {
        let density_factor = (open_bins_count as f64 / (total_items as f64 * 0.00045 + 2.2)).clamp(0.4, 20.0);
        score += (bin_capacity - post_residual) as f64 * 3.4 * density_factor;
    }

    // 4. Hierarchical Tight-Fit Reward: Exponentially weighted for near-zero residuals
    if post_residual == 0 {
        score -= 3800.0;
    } else if post_residual <= 3 {
        score -= 2400.0;
    } else if post_residual <= 8 {
        score -= 1250.0;
    }

    // 5. Residual Variance Balancing: Penalize deviation from the mean_residual trend
    let fill = (bin_capacity - post_residual) as f64;
    let target = bin_capacity as f64 - mean_residual;
    score += (fill - target).abs() * 7.2;

    // 6. Terminal Phase Heuristics: Aggressive consolidation when approaching end of stream
    if progress > 0.92 {
        if bin_residual != bin_capacity {
            score -= 9200.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powf(0.45)); 
        } else {
            score += 21000.0; 
        }
    } else if progress < 0.08 {
        score += (bin_capacity - post_residual) as f64 * 5.2;
    }

    // 7. Small-Item Packing Logic: Preventing fragmentation of small items
    if item_size < 32 && post_residual > (bin_capacity / 3) {
        score += 1200.0 * (1.1 - progress.powf(0.12));
    }

    // 8. Global Entropy Mitigation: Quadratic penalty to force uniform bin filling
    let deviation = (bin_capacity - post_residual) as f64 - (bin_capacity as f64 - mean_residual);
    score += deviation.powi(2) * 0.22;

    // 9. Targeted low-residual bonus: Boost for near-full bins
    if post_residual > 0 && post_residual <= 5 {
        score -= (6 - post_residual) as f64 * 650.0;
    }

    // 10. Lookahead parity correction: Discourage creating awkward gaps
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 4.8;
    }

    score
}

