        let utilization_factor = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= utilization_factor * 5.0;
    }

    // 4. New bin management:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Penalize opening a new bin if an existing bin is a "good enough" fit.
