    // Objective: Minimize score. 
    // We prioritize Best-Fit (minimizing post_residual) but penalize "fragmentation" 
    // where post_residual is too small to fit any future incoming items.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Score: Favor smaller post-residual (Best Fit logic)
    let mut score = post_residual as f64;

    // 2. Dead Space Penalty: If post_residual is small but > 0, it's often unusable.
    // If we have a next_item, check if it could have fit in the current post_residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Heavy penalty for creating slivers
    }

    // 3. Lookahead Logic: If the next item is large, avoid bins that would be 
    // "almost full" but leave just enough space to be inefficient.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0; // Penalty: bin won't fit the next item anyway
        }
        if post_residual >= next_item_size {
            score -= 5.0; // Reward: bin will likely accommodate the next item
        }
    }

    // 4. Global State Awareness:
    // If we have many open bins, be more aggressive at filling them.
    // If we are near the end of the stream, prioritize closing bins.
    if is_new_bin {
        // Penalize opening new bins unless necessary
        score += 40.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 50.0; // Strong deterrent against opening new bin if space exists
        }
