        // Reward bins that bring us closer to the mean residual (balancing)
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // 5. Final constraint: ensure we don't pick bins that are physically too small
    if post_residual > bin_capacity {
        score += 1000.0;
    }

