    // We favor smaller post_residuals (the standard Best-Fit behavior).

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, 
    // reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_diff) * 0.8;
    }

    // 3. Fragmentation Avoidance: If post_residual is too small to be useful for common items 
    // (e.g., < 10), it creates "dead space". Penalize this unless it's 0.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Strategic New Bin Opening: Only open a new bin if the current options are very poor.
    // If we are evaluating a brand new bin (bin_residual == bin_capacity):
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless the current open bins are 
        // extremely fragmented or we have very few bins open.
        score += 45.0 + (open_bins_count as f64 * 2.0);

        // If the item size is very large, it's less punishing to open a new bin.
        score -= (item_size as f64 * 0.4);
    }

    // 5. Global Efficiency: If fitting_bins_count is low, we are running out of options.
    // Reward bins that keep the mean_residual of open bins balanced.
