        score -= 5.0; // Reward completing a bin if it's the only one left that fits.
    }

    // 6. Progression Scaling: As the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

