    // enough space to potentially fit the next item, or conversely, 
    // pack the current item into a bin that leaves little room if the 
    // next item is also small.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize leaving "unusable" space that is too small for next_item
            score += (next_item_size - post_residual) as f64 * 0.5;
